insert into realisations (slug,title,heading,category,image,summary,description,intro,features_heading,features,process_heading,steps,faq_heading,questions,gallery,event_date,published,sort) values ('octobre-rose','Octobre Rose 2026 : sensibiliser pour mieux prévenir','Sensibiliser pour mieux prévenir','Octobre Rose 2026','img/evenement/octobre-rose-2026.png','Tout au long du mois d''octobre, Mwinue Asimame s''est mobilisée autour de la lutte contre le cancer du sein. À travers des actions de sensibilisation, de mobilisation et un partenariat avec le Centre de Diagnostic Eyano, la campagne a mis en lumière l''importance de la prévention, du dépistage précoce et de l''accès aux soins.','Retour sur Octobre Rose 2026 : sensibilisation au marché Manika, campagne virtuelle et partenariat avec le Centre de Diagnostic Eyano pour promouvoir la prévention et le dépistage du cancer du sein.','["Derrière les rubans roses, il y a des femmes qui s’interrogent, hésitent à consulter ou rencontrent des difficultés pour accéder aux soins. En octobre 2026, Mwinue Asimame s’est mobilisée pour rappeler que le cancer du sein est une réalité qui mérite une information fiable, de l’écoute et un engagement durable.","La campagne a combiné une mobilisation virtuelle et des échanges de proximité. Au marché Manika, nous sommes allés à la rencontre des femmes pour parler du cancer du sein, déconstruire certaines idées reçues et encourager chacune à demander conseil à un professionnel de santé en cas de doute. En partenariat avec le Centre de Diagnostic Eyano, nous avons également porté l’importance de la prévention et du dépistage précoce."]'::jsonb,'Les temps forts de la campagne','[["Sensibilisation virtuelle","Partager des messages de prévention et inviter chacune et chacun à parler de la santé des femmes."],["Rencontre au marché Manika","Échanger directement avec les femmes et répondre aux idées reçues par une information fiable."],["Prévention et dépistage","Promouvoir le dépistage précoce avec le Centre de Diagnostic Eyano."],["Mobilisation des partenaires","Inviter entreprises, institutions et partenaires à s’engager pour la santé des femmes."]]'::jsonb,'Une mobilisation en plusieurs étapes','[["Informer","La campagne virtuelle a fait circuler des messages pour éveiller les consciences et rappeler que le cancer du sein ne doit être ni un tabou ni une fatalité."],["Aller à la rencontre","Au marché Manika, les échanges ont permis d’aborder la maladie, de déconstruire des idées reçues et de rappeler l’importance de consulter en cas de doute."],["Agir avec un partenaire","Avec le Centre de Diagnostic Eyano, nous avons promu le dépistage et encouragé l’accès à une information et à des soins adaptés."],["Poursuivre la mobilisation","Nous remercions les femmes rencontrées, les intervenants, les partenaires et toutes les personnes ayant relayé les messages. La prévention reste un engagement de chaque jour."]]'::jsonb,'Questions autour de la campagne','[["Quel était l’objectif d’Octobre Rose 2026 ?","Informer et sensibiliser sur le cancer du sein, encourager la prévention et le dépistage précoce, et rappeler l’importance de l’accès aux soins."],["Quelles actions ont été menées ?","La mobilisation a pris la forme d’une campagne virtuelle et d’échanges de proximité avec les femmes rencontrées au marché Manika."],["Quel a été le rôle du Centre de Diagnostic Eyano ?","Ce partenariat a soutenu la sensibilisation à la prévention et la promotion du dépistage du cancer du sein."]]'::jsonb,'["img/evenement/octobre/1.jpeg"]'::jsonb,'2026-10-20',true,0) on conflict (slug) do nothing;
insert into realisations (slug,title,heading,category,image,summary,description,intro,features_heading,features,process_heading,steps,faq_heading,questions,gallery,event_date,published,sort) values ('toujours-forte','Toujours forte... Mais à quel prix ?','Prendre soin de soi sans culpabiliser','Santé mentale et bien-être','img/evenement/toujours-forte-mais-a-quel-prix.jpeg','Une rencontre consacrée à la charge mentale des femmes et aux pressions qu''elles portent souvent en silence. À travers des échanges, des conseils pratiques, un atelier de peinture et un moment de networking, cette initiative a encouragé les participantes à retrouver leur équilibre et à prendre soin d''elles-mêmes.','Retour sur une rencontre consacrée à la charge mentale des femmes, à l’équilibre personnel et à des pistes concrètes pour prendre soin de soi.','["Être toujours forte peut aussi peser. Les responsabilités et les attentes auxquelles les femmes font face peuvent laisser peu de place à leur propre repos et à leur bien-être. Cette rencontre a ouvert un espace d’échange autour de la charge mentale et des difficultés liées à la recherche d’équilibre.","Les participantes ont pu partager leurs expériences et découvrir des conseils pratiques pour prendre soin d’elles-mêmes. Un atelier de peinture et un moment de networking ont complété ce temps de rencontre, dans un cadre propice aux échanges et au soutien mutuel."]'::jsonb,'Les temps forts de la rencontre','[["Parler de la charge mentale","Mettre en mots les pressions et les responsabilités que les femmes portent parfois en silence."],["Partager les expériences","Créer un espace d’écoute et d’échange autour des réalités vécues par les participantes."],["Découvrir des pistes pratiques","Explorer des conseils pour prendre soin de son bien-être et retrouver un meilleur équilibre."],["Créer et tisser des liens","Prolonger la rencontre grâce à un atelier de peinture et un moment de networking."]]'::jsonb,'Un temps pour se recentrer','[["Ouvrir le dialogue","La rencontre a permis d’aborder la charge mentale et les attentes qui pèsent sur les femmes."],["Écouter et partager","Les participantes ont pu échanger sur leurs expériences et se sentir entendues."],["Prendre soin de soi","Des conseils pratiques ont été partagés pour soutenir le bien-être au quotidien."],["Continuer à se soutenir","L’atelier de peinture et le networking ont favorisé la créativité, les échanges et la création de liens."]]'::jsonb,'Questions autour de la rencontre','[["Quel était le thème de la rencontre ?","La rencontre portait sur la charge mentale des femmes et les pressions qu’elles peuvent porter au quotidien."],["Qu’est-ce qui était proposé aux participantes ?","Un temps d’échange, des conseils pratiques pour prendre soin de soi, un atelier de peinture et un moment de networking."],["Quel message retenir ?","Le bien-être des femmes mérite une attention réelle, au-delà des attentes qui leur demandent d’être toujours fortes."]]'::jsonb,'["img/evenement/octobre/2.jpg"]'::jsonb,'2026-08-29',true,1) on conflict (slug) do nothing;
insert into realisations (slug,title,heading,category,image,summary,description,intro,features_heading,features,process_heading,steps,faq_heading,questions,gallery,event_date,published,sort) values ('quand-amour-fait-mal','Quand l’amour fait mal','Reconnaître les violences et chercher du soutien','Droits et protection des femmes','img/evenement/quand-l''amour-fait-mal.jpeg','Une initiative de sensibilisation aux violences conjugales et à leurs conséquences sur la santé, la dignité et la vie des femmes. Cette rencontre a permis d''aborder la reconnaissance des signes d''alerte, les droits et les moyens de protection, ainsi que les chemins possibles vers la reconstruction.','Une rencontre de sensibilisation aux violences conjugales, aux signes d’alerte, aux droits des femmes et aux moyens de protection et de soutien.','["Les violences conjugales touchent à la santé, à la dignité et à la sécurité des femmes. La rencontre « Quand l’amour fait mal » a permis d’aborder cette réalité et de rappeler l’importance de pouvoir en parler.","Les échanges ont porté sur les signes d’alerte, les droits des femmes et les moyens de protection. Être mieux informée peut aider à chercher du soutien et à envisager des solutions. La reconstruction et la possibilité d’aller de l’avant font également partie du chemin."]'::jsonb,'Les sujets abordés','[["Comprendre les violences","Reconnaître que les violences conjugales affectent la santé, la dignité et la sécurité."],["Identifier les signes d’alerte","Mieux repérer les situations préoccupantes et ouvrir la voie au dialogue."],["Connaître ses droits","Rappeler les droits des femmes et les moyens de protection auxquels elles peuvent s’intéresser."],["Chercher du soutien","Encourager la recherche d’aide et rappeler que la reconstruction est possible."]]'::jsonb,'Informer pour mieux se protéger','[["Briser le silence","La rencontre a créé un espace pour parler des violences conjugales et de leurs conséquences."],["Reconnaître les signes","Les échanges ont aidé à aborder les signes d’alerte et les situations qui nécessitent une attention particulière."],["S’informer sur ses droits","Connaître les droits et les moyens de protection peut aider à envisager des solutions."],["Avancer à son rythme","La reconstruction fait partie du chemin. En cas de danger, contactez les services d’urgence ou les structures d’aide disponibles dans votre région."]]'::jsonb,'Questions autour de la sensibilisation','[["De quoi parle « Quand l’amour fait mal » ?","Cette initiative aborde les violences conjugales et leurs conséquences sur la santé, la dignité et la sécurité des femmes."],["Quels sujets ont été discutés ?","Les échanges ont porté sur les signes d’alerte, les droits des femmes, les moyens de protection et les possibilités de soutien."],["Que faire en cas de danger ?","Contactez les services d’urgence ou les structures d’aide disponibles dans votre région."]]'::jsonb,'["img/evenement/octobre/3.jpg"]'::jsonb,null,true,2) on conflict (slug) do nothing;
insert into realisations (slug,title,heading,category,image,summary,description,intro,features_heading,features,process_heading,steps,faq_heading,questions,gallery,event_date,published,sort) values ('sante-femme-decide','La santé de la femme, qui décide vraiment ?','Des choix éclairés et une écoute attentive','Santé et droits des femmes','img/evenement/la-sante-de-la-femme-qui-decide-vraiment.jpg','Un espace d''échange consacré au droit des femmes de prendre des décisions éclairées concernant leur propre santé. Cette initiative a mis l''accent sur l''importance de l''information, de l''écoute et de la liberté de choix dans tout ce qui concerne leur bien-être.','Un échange sur le droit des femmes à être informées et écoutées et à prendre part aux décisions qui concernent leur santé.','["Les décisions qui concernent la santé des femmes touchent à leur quotidien et à leur bien-être. Elles ont le droit d’être informées et écoutées, et de prendre part aux choix qui les concernent.","Cette initiative a mis en lumière l’importance de pouvoir poser des questions, d’accéder à une information compréhensible et de faire des choix éclairés. Chaque femme mérite que ses choix soient respectés et de recevoir un accompagnement adapté à sa situation."]'::jsonb,'Les principes mis en avant','[["Être informée","Accéder à une information claire et compréhensible sur sa santé."],["Être écoutée","Pouvoir exprimer ses questions, ses besoins et ses préoccupations."],["Prendre part aux décisions","Être actrice des décisions qui concernent son corps et son bien-être."],["Voir ses choix respectés","Bénéficier d’un accompagnement adapté à sa situation et à ses choix."]]'::jsonb,'Pour des décisions réellement partagées','[["Poser ses questions","Chaque femme doit pouvoir demander des explications sur les sujets qui concernent sa santé."],["Recevoir une information claire","Une information compréhensible aide à mieux saisir les options et les enjeux."],["Participer aux décisions","Les femmes ont le droit de prendre part aux décisions liées à leur santé."],["Être accompagnée","Un accompagnement adapté et le respect des choix contribuent au bien-être de chacune."]]'::jsonb,'Questions autour de la santé des femmes','[["Quel était le sujet de cet échange ?","La rencontre portait sur les décisions qui concernent la santé des femmes, leur droit à être informées et la place de leur voix."],["Pourquoi l’information et l’écoute sont-elles importantes ?","Elles permettent de poser des questions, de mieux comprendre sa situation et de prendre part aux décisions qui concernent sa santé."],["Quel message retenir ?","Chaque femme mérite le respect de ses choix et un accompagnement adapté à sa situation."]]'::jsonb,'[]'::jsonb,null,true,3) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('violences-ecouter-sans-juger','Violences faites aux femmes : écouter sans juger','Novembre 2026 · Prévention','img/evenement/novembre/1.jpg','Échange entre femmes autour de leurs droits','Quelques repères pour accueillir la parole d’une femme avec respect et sans lui imposer de décision.','Lorsqu’une femme confie une situation de violence, l’écoute peut être un premier soutien. Accueillir sa parole avec respect, sans la blâmer ni décider à sa place, l’aide à ne pas rester seule.','["Écouter, c’est laisser la personne raconter ce qu’elle souhaite, à son rythme. Évitez les questions accusatrices comme « pourquoi n’es-tu pas partie ? » et préférez des paroles simples : « je te crois », « tu ne mérites pas cela » ou « comment puis-je t’aider ? ».","Respecter ses choix est essentiel. Ne la forcez pas à porter plainte, à quitter son domicile ou à raconter son histoire à d’autres. Vous pouvez lui demander si elle se sent en sécurité maintenant et si elle souhaite être mise en contact avec une structure spécialisée.","Si elle est en danger immédiat, aidez-la à contacter les services d’urgence ou les dispositifs d’aide disponibles dans sa région, en tenant compte de sa sécurité et de ses souhaits. Ne confrontez pas la personne violente : cela pourrait accroître le risque."]'::jsonb,'Croire, écouter sans jugement et proposer des options sans imposer de décision sont des gestes de soutien.','["Violences faites aux femmes","Écoute","Prévention"]'::jsonb,4,true,'2026-11-12T12:00:00.000Z',0) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('violences-reperer-controle','Contrôle, isolement, menaces : des signaux à prendre au sérieux','Novembre 2026 · S’informer','img/evenement/novembre/2.jpg','Intervenante partageant des informations lors d’un échange','Reconnaître certains comportements préoccupants et chercher conseil auprès d’une structure compétente.','La violence ne se limite pas aux blessures visibles. Le contrôle répété, les menaces, l’humiliation ou l’isolement imposé peuvent aussi affecter la liberté, la sécurité et le bien-être d’une femme.','["Un comportement préoccupant peut notamment consister à surveiller les déplacements ou les communications, empêcher les contacts avec les proches, contrôler l’argent ou utiliser des menaces pour imposer une décision. Un signe isolé ne permet pas à lui seul de qualifier toute une situation : c’est le contexte, la répétition et le sentiment de sécurité de la personne qui comptent.","Si vous êtes concernée, vous pouvez en parler à une personne de confiance ou demander conseil à une structure spécialisée dans l’accompagnement des femmes. Si cela peut être fait sans risque, notez les faits importants et gardez les coordonnées utiles dans un endroit sûr.","Ne vous mettez pas en danger pour obtenir des preuves ou confronter la personne concernée. En cas de danger immédiat, contactez les services d’urgence ou les ressources d’aide disponibles dans votre région."]'::jsonb,'Vous n’avez pas à déterminer seule le nom de ce que vous vivez pour demander conseil et soutien.','["Violences faites aux femmes","Signaux d’alerte","Sécurité"]'::jsonb,5,true,'2026-11-12T11:00:00.000Z',1) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('soutenir-une-femme','Comment soutenir une femme confrontée à la violence','Novembre 2026 · Entraide','img/evenement/novembre/3.jpg','Femmes réunies dans un espace de dialogue et d’écoute','Écouter, respecter son rythme et l’aider à trouver un accompagnement adapté, sans la mettre en danger.','Soutenir une femme confrontée à la violence, c’est lui rappeler qu’elle n’est pas seule, tout en respectant son rythme, ses choix et les précautions nécessaires à sa sécurité.','["Proposez une écoute discrète et demandez ce qui lui serait utile aujourd’hui. Elle peut avoir besoin d’être crue, d’un accompagnement pour chercher une structure spécialisée ou simplement d’un espace où parler sans pression.","Évitez de partager son histoire sans son accord, de la culpabiliser ou de lui imposer une démarche. Ne contactez pas la personne violente et ne laissez pas de messages qui pourraient être lus par elle sans vérifier avec la femme concernée ce qui est sûr.","Vous pouvez l’aider à rechercher les services d’aide et les professionnels compétents disponibles dans sa région. Si le danger est immédiat, orientez-vous vers les services d’urgence locaux et privilégiez un moyen de communication qui ne compromet pas sa sécurité."]'::jsonb,'Le soutien le plus utile est celui qui écoute, protège la confidentialité et laisse à la femme le pouvoir de décider.','["Entraide","Accompagnement","Sécurité"]'::jsonb,5,true,'2026-11-12T10:00:00.000Z',2) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('oser-etre-soi','Oser apprendre, c’est déjà avancer','Former','img/galerie/formations/1.jpeg','Femmes réunies pendant une formation entrepreneuriale','Pourquoi la formation peut ouvrir de nouvelles portes et renforcer la confiance en ses capacités.','Apprendre ne consiste pas seulement à accumuler des connaissances. C’est aussi découvrir ses ressources, gagner confiance et se donner le droit d’imaginer de nouvelles possibilités.','["Chaque femme arrive avec un parcours, des savoirs et des talents qui lui sont propres. Une formation peut aider à les reconnaître, à les développer et à les mettre au service de projets qui ont du sens pour elle.","Il n’est pas nécessaire de tout maîtriser avant de commencer. Poser une question, essayer une nouvelle méthode ou demander conseil sont déjà des gestes d’apprentissage. On peut avancer à son rythme et revenir sur une notion autant de fois que nécessaire.","Pour choisir un prochain apprentissage, partez d’une question concrète : qu’aimeriez-vous mieux comprendre ou savoir faire ? Ensuite, cherchez une personne, un atelier ou une ressource fiable qui peut vous aider à faire un premier pas."]'::jsonb,'Votre expérience est déjà une base. Apprendre, c’est lui ajouter de nouvelles possibilités.','["Formation","Confiance","Autonomisation"]'::jsonb,4,true,'2026-11-12T09:00:00.000Z',3) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('prendre-sa-place','Prendre sa place : la voix des femmes compte','Éveiller','img/evenement/novembre/5.jpg','Intervenante partageant ses idées lors d’un échange','Une pensée sur l’écoute, la confiance et le droit de participer aux décisions.','Une parole qui se fait entendre peut ouvrir une conversation, faire connaître un besoin et participer aux décisions. La voix des femmes compte dans tous les espaces où se construit la vie collective.','["Il arrive que l’on hésite à prendre la parole, par crainte de ne pas être assez légitime ou de ne pas trouver les mots justes. Pourtant, une expérience vécue et une question sincère ont toute leur place dans un échange.","Écouter les femmes, c’est aussi reconnaître qu’elles sont concernées au premier plan par les choix qui touchent leur santé, leurs droits et leur avenir. Leur participation ne devrait pas être une exception, mais une habitude.","Une astuce pour commencer : préparez une idée ou une question avant une réunion, puis partagez-la simplement. Vous pouvez aussi vous appuyer sur une personne de confiance et proposer un espace où chacune peut s’exprimer à son tour."]'::jsonb,'Votre point de vue a de la valeur. Le partager peut aider d’autres femmes à faire entendre le leur.','["Prise de parole","Écoute","Droits des femmes"]'::jsonb,3,true,'2026-11-12T08:00:00.000Z',4) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('petits-pas','Un projet se construit aussi par petits pas','Conseils','img/evenement/novembre/4.jpg','Participantes échangeant pendant une formation','Des pistes simples pour clarifier une idée et passer progressivement à l’action.','Une idée peut sembler trop grande lorsqu’on essaie de tout réaliser en même temps. La découper en étapes accessibles aide à passer de l’envie à l’action.','["Commencez par écrire votre idée en une phrase. À qui s’adresse-t-elle ? Quel besoin cherche-t-elle à répondre ? Ces questions permettent de préciser ce que vous souhaitez faire, sans avoir à tout résoudre immédiatement.","Choisissez ensuite une petite action que vous pouvez réaliser avec les moyens disponibles : en parler à une personne concernée, recueillir quelques avis ou vous renseigner sur un sujet précis. Les retours vous aideront à ajuster la suite.","Gardez une trace de vos avancées et de ce que vous apprenez. Les étapes peuvent évoluer, et demander de l’aide n’enlève rien à votre initiative : cela peut au contraire la rendre plus solide."]'::jsonb,'Un premier pas réaliste vaut mieux qu’un plan parfait qui reste dans un tiroir.','["Conseils","Projets","Entrepreneuriat"]'::jsonb,5,true,'2026-11-12T07:00:00.000Z',5) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('connaitre-ses-droits','Connaître ses droits pour mieux les exercer','Droits','img/evenement/novembre/6.jpg','Femmes réunies pour échanger autour de leurs droits','S’informer est une première étape pour faire des choix et demander le respect de ses droits.','Les droits prennent tout leur sens lorsque les personnes peuvent les connaître, poser des questions et chercher les informations nécessaires pour les faire respecter.','["S’informer est une première étape. Lorsqu’une situation nous concerne, il peut être utile de noter ses questions, de chercher une source fiable et de demander des explications à une personne ou à un service compétent.","Les échanges entre femmes peuvent aider à faire circuler des informations et à rompre l’isolement. Ils ne remplacent pas un conseil professionnel, mais peuvent orienter vers des ressources et encourager à chercher un accompagnement adapté.","Si une information semble importante, prenez le temps d’en vérifier l’origine et la date. En cas de doute sur une démarche ou sur une situation personnelle, adressez-vous à une structure qualifiée dans votre région."]'::jsonb,'S’informer, vérifier et demander de l’aide sont des démarches légitimes pour faire valoir ses droits.','["Droits","Information","Entraide"]'::jsonb,4,true,'2026-11-12T06:00:00.000Z',6) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('sante-ecoute','Notre santé mérite d’être écoutée','Santé','img/evenement/novembre/7.jpg','Campagne Octobre Rose : notre santé, notre droit','Rappeler l’importance de poser ses questions et de chercher une information fiable.','Pouvoir parler de sa santé, être écoutée et recevoir une information compréhensible sont essentiels pour faire des choix éclairés.','["Il n’y a pas de question inutile lorsqu’il s’agit de son bien-être. Noter ses préoccupations avant un rendez-vous peut aider à ne rien oublier et à expliquer plus clairement ce que l’on ressent.","Les informations sur la santé ne se valent pas toutes. Privilégiez les sources reconnues et les conseils des professionnels de santé. Une publication partagée en ligne ne remplace pas un avis adapté à votre situation.","Prendre soin de soi ne signifie pas devoir tout gérer seule. Demander de l’aide, se faire accompagner ou solliciter une explication supplémentaire sont aussi des façons de prendre sa santé au sérieux."]'::jsonb,'Votre santé vous concerne : vous avez le droit de poser des questions et de demander une information claire.','["Santé des femmes","Écoute","Information fiable"]'::jsonb,4,true,'2026-11-12T05:00:00.000Z',7) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('bien-etre-sans-culpabilite','Prendre soin de soi sans culpabiliser','Bien-être','img/evenement/novembre/8.jpg','Participante à une rencontre d’échange entre femmes','Quelques idées pour reconnaître ses besoins et s’accorder des moments de repos.','Prendre soin de soi n’est pas un luxe ni un manque de considération pour les autres. C’est reconnaître que ses propres besoins méritent aussi de l’attention.','["Les journées peuvent être remplies de responsabilités. Au milieu de ces demandes, il est parfois difficile de remarquer sa fatigue ou de s’accorder une pause. Pourtant, écouter ses limites permet de mieux comprendre ce dont on a besoin.","Le bien-être n’a pas une seule forme. Cela peut être un moment de repos, une conversation avec une personne de confiance, une activité qui fait du bien ou le fait de demander du soutien.","Essayez de choisir un petit geste réaliste pour cette semaine, sans vous comparer aux autres. Si vous traversez une période difficile, parler à une personne de confiance ou à un professionnel peut aider."]'::jsonb,'Vous avez le droit de prendre soin de vous, même lorsque beaucoup de personnes comptent sur vous.','["Bien-être","Santé mentale","Équilibre"]'::jsonb,3,true,'2026-11-12T04:00:00.000Z',8) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('sororite','La sororité : avancer sans se comparer','Ensemble','img/evenement/novembre/9.jpg','Femmes partageant un moment de discussion','Comment l’entraide et l’encouragement mutuel peuvent nourrir l’élan de chacune.','L’entraide entre femmes ne demande pas de suivre le même chemin. Elle consiste à se reconnaître, à s’encourager et à laisser à chacune la liberté d’avancer à sa manière.','["La comparaison peut faire oublier que les parcours, les ressources et les contraintes diffèrent. Écouter sans juger et célébrer les progrès, même modestes, contribuent à des relations plus solidaires.","Un geste d’entraide peut être simple : partager une information vérifiée, recommander une ressource, prendre le temps d’écouter ou reconnaître le travail d’une autre femme.","La solidarité n’efface pas les désaccords. Elle permet de les traverser avec respect et de chercher des solutions qui ne diminuent pas la dignité de l’une ou de l’autre."]'::jsonb,'L’avancée d’une autre femme ne réduit pas la vôtre : nous pouvons progresser ensemble.','["Sororité","Entraide","Solidarité"]'::jsonb,4,true,'2026-11-12T03:00:00.000Z',9) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('oser-entreprendre','Entreprendre : commencer avec ce que l’on a','Autonomisation','img/evenement/novembre/11.jpg','Groupe de participantes à une formation entrepreneuriale','Une réflexion sur les ressources disponibles, les premiers objectifs et l’apprentissage en chemin.','Entreprendre peut commencer par une idée, une compétence ou un besoin que l’on souhaite résoudre. Il est possible d’explorer cette idée avant d’avoir toutes les réponses.','["Prenez le temps de décrire le besoin auquel votre projet veut répondre et les personnes qu’il pourrait concerner. Une première discussion avec elles peut vous apprendre ce qui leur serait réellement utile.","Faites l’inventaire de vos ressources actuelles : savoir-faire, temps disponible, matériel ou personnes prêtes à échanger. Cela permet d’imaginer une première étape adaptée à votre situation.","Renseignez-vous sur les démarches, les coûts et les soutiens possibles auprès de sources compétentes. Avancer progressivement et réévaluer son idée font partie de la construction d’un projet."]'::jsonb,'Vous n’avez pas besoin d’attendre que tout soit parfait pour commencer à explorer votre idée.','["Entrepreneuriat","Autonomie","Initiative"]'::jsonb,5,true,'2026-11-12T02:00:00.000Z',10) on conflict (slug) do nothing;
insert into articles (slug,title,category,image,alt,excerpt,intro,paragraphs,takeaway,tags,read_minutes,published,published_at,sort) values ('apprendre-toute-vie','Apprendre à tout âge, à son rythme','Former','img/evenement/novembre/10.jpg','Participante prenant la parole pendant une formation','La formation continue comme espace de découverte, de confiance et d’évolution personnelle.','L’apprentissage ne s’arrête pas à une étape de la vie. Il peut accompagner les changements, nourrir la curiosité et aider chacune à se sentir plus à l’aise dans ses choix.','["On peut apprendre de différentes façons : en suivant une formation, en observant une personne expérimentée, en lisant une ressource fiable ou en pratiquant avec d’autres.","Pour garder le cap, choisissez un objectif concret et adapté à votre disponibilité. Quelques minutes régulières peuvent aider à progresser, surtout si vous prenez le temps de revenir sur ce que vous avez découvert.","N’hésitez pas à demander des explications ou à reprendre une notion. Apprendre à son rythme n’est pas prendre du retard : c’est trouver une manière de progresser qui vous convient."]'::jsonb,'Chaque nouvelle compétence, même petite, peut devenir une ressource pour la suite.','["Apprentissage","Formation","Confiance"]'::jsonb,4,true,'2026-11-12T01:00:00.000Z',11) on conflict (slug) do nothing;
