insert into team (name,role,photo,bio,sort) values ('Dr. Nadège Tshinate','Fondatrice','img/team/1.jpeg','À l''origine de Mwinue Asimame, elle porte une vision engagée pour la promotion de la santé, la défense des droits et l''autonomisation des femmes. Par son leadership et sa détermination, elle œuvre à faire de cette vision une réalité au service des communautés.',0);
insert into team (name,role,photo,bio,sort) values ('Dr. Rachelle Kabongo','Co-fondatrice','img/team/2.jpeg','Animée par la même ambition, elle contribue au développement de Mwinue Asimame et à la concrétisation de ses initiatives. Son engagement participe à renforcer les actions de l''association en faveur de l''épanouissement et de l''émancipation des femmes.',1);
insert into testimonials (name,role,photo,content,sort) values ('Dr. Nadège Tshinate','Fondatrice, Mwinue Asimame','img/avatar/avatar-2.jpeg','Mwinue Asimame est née d''une conviction profonde : chaque femme mérite de connaître ses droits, de préserver sa santé et de disposer des moyens nécessaires pour construire son avenir.',0);
insert into testimonials (name,role,photo,content,sort) values ('Dr. Rachelle Kabongo','Co-fondatrice, Mwinue Asimame','img/avatar/avatar-3.jpeg','Notre engagement est de faire de la sensibilisation, de la formation et de l''accompagnement des leviers concrets pour renforcer la place et l''autonomie des femmes dans la société.',1);
insert into testimonials (name,role,photo,content,sort) values ('Mme Monique Mbayo','Responsable Marketing & Communication','img/avatar/avatar-4.jpg','Les initiatives en faveur des femmes sont essentielles pour bâtir une société plus consciente, solidaire et équitable. L''engagement de Mwinue Asimame contribue à cette dynamique.',2);
