insert into settings (key,value) values ('latest_activity','{"eyebrow":"Dernière activité","title":"Unis contre les cancers : de la sensibilisation à l''action","text":"Sous le haut patronage de Madame la Gouverneure du Lualaba, le Ministère Provincial de la Santé, Éducation, Affaires Sociales et Humanitaires, Genre, Famille et Enfant a organisé, le 6 novembre 2026, une matinée de sensibilisation consacrée à la prévention, au dépistage précoce et à la prise en charge des cancers.","image":"img/evenement/cancers-sensibilisation.png","badge_title":"Ensemble contre les cancers","badge_date":"6 novembre 2026","bullets":[["Sensibilisation et prévention","échanges autour des différents types de cancers et de l''importance du dépistage précoce."],["Expertise médicale","interventions de spécialistes sur les cancers pédiatriques, du sein, du col de l''utérus et de la prostate."],["Accompagnement et information","lutte contre les fausses croyances, santé mentale et soutien psychosocial."]],"button_label":"Voir toutes nos activités","button_link":"services.html"}'::jsonb) on conflict (key) do nothing;
